import sys

MOD = 10**9 + 7

def calculate_partitions(n, k, weights):
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    prefix_sum = [0] * (n + 1)

    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + weights[i - 1]
        for j in range(1, min(i, k) + 1):
            if j == 1:
                dp[i][j] = (prefix_sum[i] * i) % MOD
            else:
                dp[i][j] = ((dp[i - 1][j] * (i - 1)) + (dp[i - 1][j - 1] * (prefix_sum[i] - prefix_sum[i - j]))) % MOD

    return dp[n][k]

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    weights = list(map(int, data[2:]))

    result = calculate_partitions(n, k, weights)
    print(result)

