MOD = 10**9 + 7

def factorial(n):
    if n < 2:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = result * i % MOD
    return result

def power(base, exponent):
    result = 1
    while exponent > 0:
        if exponent % 2 == 1:
            result = result * base % MOD
        base = base * base % MOD
        exponent //= 2
    return result

def inverse(a):
    return power(a, MOD - 2)

def solve(n, k, weights):
    total_weight = sum(weights)
    ways_to_choose_k_subsets = power(factorial(n), MOD - 2) * factorial(k) % MOD
    total_sum_of_weights = (total_weight * ways_to_choose_k_subsets * power(factorial(n - k), MOD - 2)) % MOD
    return total_sum_of_weights

